"""Prepare one beginner revision; never mutate approved narration or media."""
from pathlib import Path
import json,hashlib,datetime,copy
R=Path(__file__).resolve().parents[4];P=R/'projects/game-lighting-history-01'
D=Path(__file__).parent
def rd(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def wr(p,x):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
changes=[]
def add(key,ko,en,goal,label):changes.append(dict(key=key,ko=ko,en=en,beginnerGoal=goal,screenLabel=label))

add('02-p2','입체 물체의 겉면을 작은 삼각형들로 나눕니다. 카메라에서 본 모양을 평평한 화면으로 옮기고, 어느 칸을 덮는지 찾는 것이 래스터화입니다. 겹친 면 중 앞에 있는 것을 고르는 깊이 검사도 합니다.','A 3D object’s surface is divided into small triangles. Rasterization projects them onto the flat image and finds the samples they cover. A depth test helps select the surface in front when surfaces overlap.','삼각형·투영·표본을 일상어로 먼저 풀기','입체 표면 → 화면의 칸 → 앞쪽 표면')
add('02-p4','손전등을 종이에 똑바로 비출 때와 기울여 비출 때를 떠올려 보세요. 방향이 얼마나 마주 보는지 나타내는 계산이 내적입니다. 길이를 일로 맞춘 두 화살표가 같은 방향이면 일, 육십 도 벌어지면 영 점 오입니다. 지금의 단순한 모델에서는 다른 조건이 같을 때 방향에 따른 밝기 몫이 절반이 됩니다.','Imagine illuminating paper head-on, then at a slant. A dot product measures how closely the directions align. For two arrows normalized to length one, alignment gives one and a sixty-degree angle gives 0.5. In this simple model, with other inputs fixed, the directional contribution is halved.','내적의 의미를 직관→수치→적용범위 순서로','정면 1 / 60° 0.5 · 방향만 비교')
add('02-p5','여기서 벡터는 방향과 길이를 가진 화살표입니다. 단위 벡터는 길이를 일로 맞춘 화살표고요. 길이를 맞춰야 방향만 비교할 수 있습니다. 하지만 잘 마주 본다고 언제나 밝지는 않습니다. 중간에 벽이 있으면 빛이 막힙니다. 방향 계산과 가림 검사는 별개입니다.','A vector is an arrow with a direction and length. A unit vector has length one, allowing us to compare direction without mixing in length. Good alignment does not guarantee illumination: a wall in between can block the light. Directional response and visibility are separate tests.','단위벡터와 방향/가림 차이','화살표 길이를 1로 / 중간 벽은 따로 검사')
add('02-p6','화면의 긴 식은 들어온 빛을 모으는 장부입니다. 스스로 빛나는 양에, 다른 곳에서 와서 반사된 양을 더합니다. 재질은 어떤 빛을 얼마나 돌려보낼지 정합니다. 여러 방향의 기여를 모두 합친다는 표시가 적분 기호입니다.','The long equation is a ledger of light. It adds emitted light to light arriving from elsewhere and reflected toward us. The material determines how much is reflected. The integral indicates that contributions from many directions are combined.','방정식을 해독하지 않아도 의미를 이해','스스로 내는 빛 + 들어와 반사된 빛')
add('02-p7','식을 외울 필요는 없습니다. 앞으로는 세 질문만 따라가세요. 어떤 면이 보이나, 빛이 그 면까지 오나, 그 면은 빛을 얼마나 반사하나입니다. 게임은 이 일을 전부 새로 계산하기도 하고, 일부 답을 미리 저장해 읽기도 합니다.','You do not need to memorize the equation. Follow three questions: which surface is visible, can light reach it, and how does that surface reflect it? Games may recompute these answers or store some of them in advance.','시청자의 인지 과제 제한','보이는 면 → 빛의 도착 → 표면의 반응')
add('02-p8','레이는 한 점에서 한 방향으로 뻗는 검사선입니다. 카메라에서 보내면 먼저 보이는 물체를 찾고, 표면에서 광원으로 보내면 중간의 장애물을 찾습니다. 반사 방향으로 보내면 거울에 비칠 다른 물체를 찾을 수 있습니다.','A ray is a test line extending from a point in a direction. From the camera it can find the first visible object; from a surface toward a light it can test for blockers. A reflected ray can find an object visible in a mirror.','레이를 빛그림 장식과 구분','레이 = 한 방향으로 무엇과 만나는지 검사')
add('03-p2','색상표는 같은 벽 무늬를 밝게, 또는 어둡게 보여 줄 색들의 목록입니다. 코드의 비트 이동은 구역 밝기를 거친 단계로 묶어 목록 번호를 만드는 계산입니다. 여기에 추가 밝기와 벽 방향 보정을 적용하고, 쓸 수 있는 번호 범위를 넘지 않게 합니다.','A colormap provides colors that display the same wall pattern at different brightnesses. The code’s bit shift groups sector brightness into coarse levels to form an index. Extra lighting and orientation adjustments are applied, with the index restricted to its valid range.','비트이동/인덱스 대신 먼저 색상표 역할','밝기 값 → 목록 번호 → 어두운/밝은 색')
add('04-p1','벽돌 무늬를 붙이는 디지털 그림을 텍스처라고 합니다. 퀘이크는 무늬와 별도로, 벽의 어느 곳이 얼마나 밝은지 적은 그림도 저장합니다. 이 조명용 그림이 라이트맵입니다. 무늬 그림과 빛 그림, 두 장을 구별해 보죠.','A texture can be a digital picture applied to a surface, such as brickwork. Quake stores another image describing illumination at different places on that wall. This lighting image is the lightmap. Separate the pattern picture from the light picture.','텍스처를 먼저 정의하고 라이트맵 소개','벽 무늬 그림 / 조명 그림')
add('04-p2','벽 전체를 연속해서 계산하기는 어려우니 대표 지점을 찍습니다. 이것이 표본입니다. 각 지점에서 광원까지 가려지는지 검사하고 방향과 거리, 빛의 세기를 반영합니다. 이 결과를 게임 전에 계산해 두는 작업을 베이크라고 부릅니다.','Instead of computing every point on a continuous wall, we choose representative samples. At each sample we test visibility to the light and account for direction, distance and intensity. Computing these results before gameplay is called baking.','표본/베이크 선행정의','대표 지점에서 계산 → 미리 저장 = 베이크')
add('04-p6','실행할 때에는 벽 무늬를 읽고, 같은 표면에 해당하는 조명 값을 읽어 조합합니다. 그림 속 어디를 읽을지 가리키는 주소가 텍스처 좌표입니다. 두 그림의 주소 배치나 칸 수는 달라도 됩니다.','At runtime, the renderer reads the wall pattern and the lighting value for the corresponding surface location, then combines them. Texture coordinates specify where to look in an image. The two images can use different layouts and resolutions.','좌표=주소 비유, 두해상도 구분','표면 위치 → 두 그림의 주소 → 조합')
add('04-p7','빛이 조명에서 벽으로 바로 오면 직접광입니다. 다른 벽에 반사된 뒤 오면 간접광이고요. 퀘이크 투는 표면을 나눈 작은 패치 사이의 반사광도 계산해 라이트맵에 더했습니다. 직접 빛이 닿지 않는 곳에도 밝기가 생기는 이유입니다.','Direct light travels from a light to a surface. Indirect light arrives after reflecting off another surface. Quake II’s tools also computed reflected contributions between surface patches and added them to lightmap samples, illuminating places without direct exposure.','직접/간접/패치 정의','조명 → 벽 = 직접 / 다른 벽 경유 = 간접')
add('04f-p1','화면의 한 칸은 픽셀, 텍스처 그림의 한 칸은 텍셀입니다. 둘은 일대일이 아닙니다. 먼 바닥을 보면 픽셀 하나 안에 많은 텍셀이 들어갑니다. 그중 하나만 집으면 카메라가 조금 움직일 때 선택이 바뀌어 무늬가 흔들릴 수 있습니다.','A pixel belongs to the output image; a texel belongs to a texture. They are not necessarily one-to-one. A distant floor can put many texels inside one pixel’s footprint. Choosing just one can make the pattern fluctuate as the camera moves.','픽셀과 텍셀 분리','화면의 칸 = 픽셀 / 원본 그림의 칸 = 텍셀')
add('04f-p3','칸 사이의 색이 필요하면 가까운 네 칸을 섞습니다. 가까운 칸은 많이, 먼 칸은 적게 넣는 비중을 가중치라고 합니다. 한 크기의 그림에서 이 일을 하는 방법이 바이리니어 필터입니다.','When a value is needed between texture samples, bilinear filtering combines four neighbors. Their weights determine how much each contributes, with closer samples contributing more. This operation works within one texture level.','가중평균을 먼저 정의','네 칸의 색 × 각 비중 → 더하기')
add('04f-p5','멀리 갈수록 더 작은 밉맵을 고르지만, 갑자기 바꾸면 티가 날 수 있습니다. 트라이리니어는 이웃한 두 크기에서 읽은 결과를 다시 섞습니다. 네 칸 사이를 섞고, 두 크기 사이도 섞는다고 이해하면 됩니다.','As distance increases, a smaller mip level may be appropriate, but abrupt switches can be visible. Trilinear filtering blends the bilinear results from two neighboring mip levels: interpolation within each level and between levels.','보간/레벨 용어 평이하게','그림 안의 네 칸 + 두 그림 크기 사이')
add('04t-p3','큰 그림 전체의 재료를 멀리 있는 메모리에서 계속 가져오면 이동 비용이 듭니다. 작은 타일에 필요한 자료를 칩 안의 가까운 저장 공간에 모아 처리하면, 이런 왕복을 줄일 수 있습니다. 타일을 완성한 뒤 결과를 내보냅니다.','Repeatedly moving data to and from external memory costs bandwidth. Keeping a small tile’s working data in nearby on-chip storage can reduce those trips. The tile is completed and its result is then written out.','메모리/버퍼 비용 구체화','작은 작업판 안에서 처리 → 완성 결과 저장')
add('04t-p4','셰이딩은 표면의 색과 밝기를 계산하는 일입니다. 파워브이알의 티비디알은 먼저 보이는 표면을 가려낸 뒤 필요한 셰이딩을 하는 구조입니다. 이름의 디퍼드는 뒤로 미룬다는 뜻입니다. 뒤에서 나올 디퍼드 셰이딩은 미루는 일이 다릅니다.','Shading computes a surface’s color and illumination. PowerVR’s TBDR resolves visibility before performing needed shading. Deferred means postponed. The later technique called deferred shading postpones a different part of the work.','셰이딩/디퍼드 뜻과 동음이의','무엇을 뒤로 미루는지 확인')
add('04t-p6','앞의 벽에 완전히 가린 물체는 색을 계산하지 않아도 됩니다. 다만 유리처럼 뒤가 보이거나 일부를 잘라 버리는 재질은 다르게 다뤄야 합니다. 다른 GPU도 깊이를 일찍 검사하고 가까운 자료를 재사용합니다. 그래서 타일이라는 이름만으로 속도를 단정할 수 없습니다.','A surface fully hidden behind an opaque wall may not need shading. Transparent or discarding materials require different handling. Other GPUs also test depth early and reuse nearby data. The word tile alone does not determine performance.','earlyZ/cache/discard를 역할로 설명','완전히 가린 면 / 뒤가 비치는 면 구분')
add('07-p5','손전등 앞에 손을 두면 손 뒤로 빛이 닿지 않는 공간이 생깁니다. 섀도 볼륨은 그 공간을 입체로 만드는 방법입니다. 광원에서 본 물체의 테두리를 뒤로 늘여 옆면을 잇습니다. 둠 쓰리의 공개 코드에서도 이런 구성을 확인할 수 있습니다.','Put a hand in front of a flashlight and a region behind it loses that light. Shadow volumes construct this region in 3D. Edges on the light-facing silhouette are extruded and connected into side faces, as seen in DOOM 3’s public code.','그림자볼륨 실생활 원인부터','물체의 테두리 → 빛 반대쪽 그늘 공간')
add('07-p6','이제 화면에 보이는 점이 그 공간 안에 있는지 검사합니다. 스텐실 버퍼는 화면 위치마다 검사 숫자를 적어 두는 메모입니다. 그늘 속에 있다고 나오면 해당 조명의 빛을 더하지 않습니다. 검은 그림을 붙이는 것과 다릅니다.','We test whether the visible surface point lies inside that region. The stencil buffer stores test values at image locations. If a point is in shadow, that light’s contribution is omitted; this is not simply a black image pasted onto the scene.','스텐실 버퍼를 값저장+용도 연결','위치별 검사 메모 → 이 조명을 더할지 결정')
add('08-p2','밝기 하나만 저장하면 빛이 어느 쪽에서 왔는지 잃습니다. 밸브의 자료는 세 기준 방향에 해당하는 조명을 따로 저장합니다. 이 기준 방향을 기저라고 합니다. 그림의 세 화살표는 새 조명 세 개가 아니라, 방향 정보를 나누는 기준입니다.','One brightness value loses the direction from which light arrived. Valve’s example stores lighting for three reference directions, called a basis. The three arrows are not three newly added lights; they define components of stored directional information.','기저를 기준방향으로 풀기','밝기 하나 → 방향별 조명 세 몫')
add('08-p3','각 기준 방향을 표면이 얼마나 향하는지 구하고, 그 비중만큼 저장된 색을 섞습니다. 코드의 곱하기는 각 몫을 구하고, 더하기는 모으는 단계입니다. 이 자료의 제한된 내적 가중치와 다른 버전의 제곱 가중치 식은 구별합니다.','Determine how closely the surface faces each basis direction and blend the stored colors using those weights. Multiplication computes each contribution; addition combines them. This source’s clamped dot-product example is distinct from squared-weight formulations in other versions.','코드 연산을 조명몫과 연결','방향별 저장색 × 비중 → 합')
add('08-p7','벽의 라이트맵은 벽에 붙어 있지만, 캐릭터는 움직입니다. 그래서 방 안의 여러 위치에 조명 값을 준비해 가까운 정보를 읽을 수 있습니다. 이런 조회용 공간 표본을 프로브라고 부릅니다. 당시 앰비언트 큐브와 다른 엔진의 프로브는 정보를 담는 방식이 다릅니다.','A wall lightmap stays attached to the wall, but a character moves. Lighting can instead be prepared at locations in the room and nearby information retrieved. Such spatial samples are commonly called probes. The historical ambient cube and other engines’ probe systems use different representations.','프로브 공간표본 정의','벽에 붙은 저장 / 공간 위치의 저장')
add('09-p1','조명 자리에 카메라가 있다고 생각해 보세요. 색 사진 대신, 각 방향에서 처음 만난 표면의 깊이를 적습니다. 이것이 섀도 맵입니다. 이제 우리가 보는 표면점도 조명 쪽에서 바라보면, 먼저 만난 물체 뒤에 있는지 비교할 수 있습니다.','Imagine a camera at the light. Instead of colors, it records depth to the first surface in each image direction: a shadow map. Projecting a visible surface point into that light view lets us check whether it lies behind the first recorded surface.','광원좌표를 광원시점으로 구체화','조명 시점의 첫 표면 기록 → 뒤인지 비교')
add('09-p2','여기서는 작은 깊이가 가깝고 큰 깊이가 멉니다. 검사할 점이 기록보다 멀면 앞의 물체가 빛을 막습니다. 자로 잴 때 시작점과 단위를 맞추듯, 두 깊이는 같은 조명 시점의 기준으로 비교해야 합니다.','In this example, smaller depth means nearer and larger means farther. A test point behind the stored surface is blocked. Just as rulers need matching origins and units, both depths must be compared using the same light-view convention.','같은좌표/규약 이유','같은 기준으로 잰 깊이끼리 비교')
add('09-p5','컴퓨터가 저장하는 숫자에는 정밀도 한계가 있습니다. 같은 표면인데 두 번 구한 깊이가 조금 달라, 자기 앞에 장애물이 있다고 오해할 수 있죠. 비교할 때 작은 여유를 주는 보정이 바이어스입니다.','Stored numbers have limited precision. Two computations of the same surface depth can differ slightly, making it appear to block itself. Bias adds a small adjustment to the comparison to reduce this self-shadowing error.','수치오차와 바이어스 원인','같은 표면의 작은 오차 → 비교 여유')
add('09-p7','한 칸만 검사하면 경계가 거칠어집니다. 피시에프는 주변 여러 칸에서 각각 빛이 통하는지 물어보고, 통한다는 답의 비율을 씁니다. 거리 숫자를 먼저 섞는 것이 아니라, 검사 결과를 섞는 방법입니다.','A single shadow-map lookup can give a hard jagged boundary. PCF tests several nearby locations and averages the lit results. It combines comparison outcomes, rather than averaging depths before one comparison.','PCF 비교결과평균 쉬운질문','주변 칸마다 통과? → 통과 비율')
add('09-p9','필터는 주변 결과를 섞는 범위입니다. 피 씨 에스 에스는 막는 물체와 그림자를 받는 면의 관계로 그 범위를 바꿉니다. 배리언스 섀도 맵은 깊이의 평균과 제곱 평균을 저장해 가림을 어림합니다. 서로 다른 근사이며 빛이 새는 등 한계도 있습니다.','A filter’s extent controls the neighborhood combined. PCSS adjusts it using the relationship between blockers and receivers. Variance shadow maps store depth’s first and second moments to approximate visibility. These are different approximations, with limitations such as light leaking in the latter.','수광면/필터폭/모멘트를 역할로','받는 면과 막는 물체 / 섞는 범위')
add('09a-p5','검사할 점이 가까운 구간인지 먼 구간인지 찾아 그 구간의 맵을 읽습니다. 이음새에서는 두 결과를 섞습니다. 카메라가 조금 움직일 때 격자도 계속 미끄러지면 그림자가 떨릴 수 있어, 격자 칸에 맞춰 움직이는 안정화도 씁니다.','Choose the shadow map for the point’s camera-distance interval and blend results near transitions. Tiny camera motions can make the projected grid slide and shadows shimmer, so stabilization can snap the projection to the texel grid.','맵선택/텍셀스냅 시각적원인','거리로 맵 선택 / 경계 섞기 / 격자 안정화')
add('09b-p1','이제 같은 화면을 어떤 작업 순서로 칠할지 보죠. 포워드는 표면을 그릴 때 그 재질과 관련 조명들을 함께 계산해 색을 냅니다. 벽의 이 픽셀을 맡았다면, 그 자리의 빛 계산까지 마치는 방식입니다.','Now compare work order for the same image. Forward shading evaluates the material and relevant lights while drawing a surface. When processing this wall pixel, it computes the lighting contribution as part of that surface’s shading.','같은픽셀 작업순서 출발','포워드: 표면 처리 중 조명도 계산')
add('09b-p2','디퍼드는 조명 계산을 뒤로 미룹니다. 먼저 보이는 표면의 기본색, 방향, 깊이 같은 정보를 화면 위치별로 적습니다. 이 표면 정보 묶음이 지 버퍼입니다. 다음 조명 작업이 그 메모를 읽어 색을 계산합니다.','Deferred shading postpones lighting. It first records visible-surface properties such as base color, orientation and depth by image position. This collection is the G-buffer. A later lighting stage reads those records to compute illumination.','버퍼의정의/저장정보/후속사용','디퍼드: 표면 메모 → 나중에 조명 계산')
add('09b-p3','기본색은 조명까지 합친 최종 색이 아닙니다. 법선은 표면 방향, 거칠기는 반사가 얼마나 넓게 퍼지는지를 다루는 재질 값입니다. 언리얼의 책 모형 시연에서는 이런 재질 정보를 따로 살펴보고 그림으로 내보냅니다. 물체에 붙인 재질 그림과 현재 화면의 지 버퍼는 저장 기준이 다르지만, 표면 정보의 종류를 구별하는 데 도움이 됩니다.','Base color is not the final lit color. Normals encode orientation; roughness controls the spread of a material’s reflection. The Unreal book example inspects and exports material data separately. Object textures and the current frame’s G-buffer use different domains, but the demonstration helps distinguish property types.','재질그림과Gbuffer 혼동방지/정보정의','기본색·방향·거칠기 ≠ 최종 조명색')
add('09b-p4','같은 벽의 한 픽셀만 따라가 보죠. 재질까지 반영한 두 조명의 몫이 영 점 이오와 영 점 삼오라면 합은 영 점 육입니다. 포워드는 표면을 그리면서 이 합을 만듭니다. 디퍼드는 표면 정보를 적은 뒤 다음 단계에서 합칩니다. 조명을 더하는 목표는 같고, 언제 어떤 정보를 가지고 계산하는지가 다릅니다.','Follow one pixel on the same wall. Suppose two lighting contributions, already accounting for the material, are 0.25 and 0.35; their sum is 0.6. Forward computes this during surface shading. Deferred records surface data first, then combines lighting in a later stage. The goal is the same; the ordering and intermediate data differ.','하나의픽셀 수치완결비교','같은 픽셀 · 0.25 + 0.35 = 0.60')
add('09b-p5','조명이 오른쪽 벽에만 닿는다면 왼쪽 픽셀에는 계산할 필요가 없습니다. 이런 제외 작업은 두 방식 모두에 쓸 수 있습니다. 화면의 네 물체와 세 조명은 순서 설명용입니다. 포워드가 언제나 모든 조명을 계산한다거나 디퍼드가 무조건 빠르다는 뜻은 아닙니다.','If a light only reaches the right wall, pixels on the left need not evaluate it. Both approaches can cull irrelevant lights. The four objects and three lights illustrate ordering, not a claim that Forward always evaluates every light or Deferred always wins.','최적화/성능 고정관념예방','닿지 않는 조명 제외는 두 방식 모두 가능')
add('09b-p7','메모를 남기면 다음 작업이 쓰기 편하지만, 쓰고 읽는 비용이 듭니다. 지 버퍼도 같습니다. 또 한 픽셀에 가장 앞 표면 한 겹만 적으면, 그 뒤가 비치는 유리창처럼 여러 층이 필요한 장면은 이 정보만으로 완성할 수 없습니다.','A record is useful to a later operation, but writing and reading it costs work and bandwidth. The G-buffer has that tradeoff. A record of only one frontmost surface cannot by itself describe all the layers needed for transparent glass.','대역폭/단일층 한계 구체화','메모 왕복 비용 / 한 칸에 한 표면만')
add('09b-p9','패스는 화면을 만들기 위한 작업 한 차례를 뜻합니다. 그래서 불투명 물체는 디퍼드로 그리고, 유리는 별도의 포워드 패스로 합칠 수 있습니다. 라이트 프리패스는 법선과 깊이로 조명부터 구한 뒤 재질을 결합하는 또 다른 절충입니다.','A pass is a stage or round of rendering work. An engine can shade opaque objects with Deferred and composite glass in a separate Forward pass. Light pre-pass is another compromise: lighting from depth and normals, followed by material combination.','패스를 사용전 해설','패스 = 작업 한 차례 / 유리는 별도 처리 가능')
add('09b-p10','포워드도 지금 쓰입니다. 로보 리콜은 머리 움직임에 화면이 따라오는 브이알 게임입니다. 가장자리를 또렷하게 만드는 멀티샘플 처리와 필요한 기능을 함께 고려해 포워드 경로를 선택한 사례입니다. 이 시연은 그 선택이 보이는 결과와 어떻게 연결되는지 보려는 것입니다.','Forward remains in use. Robo Recall is a VR game whose view follows head movement. Its Forward path was chosen with multisampling and required features in mind. We use this demonstration to connect that engineering choice to visible image quality.','RoboRecall등장이유 명료화','VR의 가장자리 품질과 기능 선택 사례')
add('10-p1','빛을 직접 막는 그림자까지 그렸는데 구석이 떠 보일 수 있습니다. 주변이 트인 점보다 벽 틈의 점이 여러 방향에서 빛을 받기 어렵기 때문입니다. 화면 공간 앰비언트 오클루전, 줄여서 에스에스에이오는 화면에 기록한 깊이로 이 주변 가림을 어림합니다.','Even after direct shadows, corners can appear ungrounded. A point in a crevice has fewer open directions for environmental illumination than an exposed point. Screen-space ambient occlusion, SSAO, estimates this nearby occlusion using recorded screen depth.','환경가림 문제부터 약어소개','트인 곳 / 막힌 틈 → 주변 가림 근사')
add('10-p2','화면 공간이라는 말은 현재 카메라에 보인 정보를 바탕으로 한다는 뜻입니다. 에스에스에이오는 장면 전체의 빛을 다시 추적하지 않습니다. 주변 화면 칸의 깊이를 살펴, 이 표면 주위가 얼마나 막혀 있을지 추정합니다.','Screen-space means operating on information available in the current camera image. SSAO does not trace all lighting through the scene. It examines nearby screen-depth samples to estimate occlusion around a surface.','화면공간 정의','현재 카메라에 남은 정보만 사용')

add('g00','게임 화면은 작은 색 칸, 픽셀로 이루어집니다. 이 칸들을 채워 그림 한 장을 만들고, 그런 그림을 빠르게 바꾸면 움직임이 됩니다. 한 장을 프레임, 입체 장면에서 그림을 만드는 일을 렌더링이라고 합니다. 지금은 이 화면의 한 칸에 무엇이 보여야 하는지부터 생각해 보겠습니다.','A game image consists of small color cells called pixels. Filling them produces one frame, and displaying successive frames creates motion. Rendering turns the scene into an image. Start by asking what should appear at one position in this view.','픽셀·프레임·렌더링 사전설명','픽셀 → 한 장의 프레임 → 연속 화면')
add('g01','카메라가 보는 면을 따라가 보세요. 물체는 입체지만 화면은 평평합니다. 그래서 같은 화면 자리에 앞의 벽과 뒤의 물체가 겹칠 수 있습니다. 앞뒤 순서를 알려 주는 값이 깊이입니다. 표면이 어디를 향하는지 알려 주는 법선과는 다르죠. 위치, 앞뒤, 방향을 따로 기록해야 빛도 제대로 계산할 수 있습니다.','Follow the surfaces visible to the camera. Objects are three-dimensional, but the image is flat, so front and back surfaces can overlap at one image location. Depth distinguishes their order. A normal instead describes surface orientation. Position, depth and direction are different inputs to shading.','깊이와법선의차이','깊이 = 앞뒤 / 법선 = 표면 방향')
add('g14','방의 벽에서 반복되는 무늬와 넓게 번진 밝기를 따로 보세요. 무늬 그림을 바꿔도 조명 계산이 저절로 새로 되지는 않습니다. 거꾸로 조명 그림을 더 촘촘히 만들었다고 벽돌 원본 그림까지 세밀해지는 것도 아닙니다. 두 자료의 역할이 다릅니다.','Separate the repeating wall pattern from the broad illumination in these rooms. Changing the pattern does not automatically recompute lighting. Increasing lightmap resolution does not add detail to the original brick picture either. The two data sources serve different purposes.','텍스처와라이트맵 역할복습','무늬 해상도 / 조명 해상도 따로')
add('g12','벽의 색을 바꾸는 일은 그림의 재료를 바꾸는 일입니다. 조명을 옮기는 일은 빛이 도착하는 경로를 바꾸는 일이고요. 지금은 방의 구조와 밝기를 관찰하는 화면입니다. 이 둘 중 무엇을 수정했느냐에 따라 다시 만들어야 할 정보도 달라진다는 점을 기억해 두세요.','Changing a wall’s color changes a material input; moving a light changes light paths. This view lets us inspect the room’s structure and illumination. Which information needs rebuilding depends on which input was changed.','입력변경과재계산 인과','무엇을 바꿨나 → 어떤 답이 낡았나')
add('g19','비스듬한 계단의 가느다란 선을 보세요. 픽셀 한 칸 안에 선과 빈 공간이 함께 들어갈 수 있습니다. 한 위치만 검사하면 선을 놓치기도 하죠. 여러 위치에서 선이 덮는지 검사하면 가장자리를 더 안정적으로 표현할 수 있습니다. 이것이 뒤에서 볼 멀티샘플의 출발점입니다. 벽 무늬를 섞어 읽는 텍스처 필터와는 검사하는 대상이 다릅니다.','Look at the thin stair edges at an angle. One pixel can contain both an edge and empty space. Testing one location may miss that edge; testing coverage at several locations can represent it more consistently. This motivates multisampling later. Texture filtering instead combines values from a surface texture.','MSAA이전 픽셀덮임 선행설명','선이 픽셀을 얼마나 덮는가?')
add('g25','로봇의 몸 안쪽 명암과 바깥 윤곽을 따로 보세요. 표면 방향을 계산할 때 쓰는 화살표만 바꾸면 작은 홈처럼 보이게 할 수 있습니다. 하지만 물체를 옆에서 봤을 때 튀어나오는 실제 모양까지 생기지는 않죠. 조명 계산용 방향과 실제 입체 모양을 구별하는 것이 법선맵의 핵심입니다.','Separate the robot’s interior shading from its silhouette. Changing the directions used for lighting can suggest grooves, but it does not create the actual protruding shape visible in silhouette. Normal mapping changes shading directions, not the underlying geometry.','법선맵이가능/불가능한일','표면 명암 변화 ≠ 실제 윤곽 변화')
add('g27','한 값에 모두 섞어 저장하면 나중에 방향을 바꿔 읽기 어렵습니다. 방향별로 나누어 저장하면 표면이 향하는 쪽의 몫을 더 많이 고를 수 있습니다. 그림자를 새로 만드는 것과는 다릅니다. 지금 게임에서는 완성된 명암을 보고, 입체 도식에서는 그 명암을 이루는 방향별 몫을 나누어 보는 것입니다.','A single combined value loses directional information. Keeping separate directional components allows a surface to select more of the contribution it faces. This does not independently generate new moving shadows. The game shows completed shading; the diagram separates the directional contributions.','방향별저장 필요성 반복예제로','한 값에 합치기 / 방향별로 나눠 저장')
add('g29','방 안의 점들은 작은 조명들이 아니라 조명 정보를 읽어 올 장소라고 생각하세요. 벽의 그림은 벽에 붙어 있고, 이 점들은 높이까지 있는 공간에 놓여 있습니다. 캐릭터가 움직이면 가까운 점들의 정보를 이용합니다. 점 사이에서 값이 갑자기 튀지 않게 섞어 읽는 일을 보간, 즉 사잇값을 구하는 계산이라고 합니다. 지금 언리얼은 하프라이프 투와 다른 엔진 사례입니다.','Think of these points as locations storing lighting information, not little light sources. A wall texture stays on a surface; these samples occupy volume, including height. A moving character uses nearby information. Interpolation combines values between samples to avoid abrupt changes. This Unreal example is a different engine from Half-Life 2.','프로브/보간 정의','공간 표본 → 가까운 값들을 섞어 읽기')
add('g31','계산을 미리 해 두면 게임 중에는 답을 읽으면 됩니다. 대신 방이나 조명을 고쳤다면 예전 답이 여전히 맞는지 확인해야 합니다. 이 편집 화면은 방을 살펴보는 과정입니다. 화면이 재생되는 시간은 베이크 계산 시간이 아닙니다.','Precomputation lets the game read prepared answers. Changing the room or lighting may invalidate them. This editor view inspects a scene; its playback time is not a measurement of baking time.','시간비용교환 일상어로','미리 계산의 이득 / 수정 뒤 답의 유효성')
add('g32','앞에서 말한 가중치는 섞을 비중입니다. 같은 재료라도 어느 것을 많이 넣는지에 따라 결과가 달라지죠. 방향별 라이트맵도 저장된 세 몫 가운데 표면이 더 향하는 쪽의 비중을 높입니다.\n\n지금은 로봇을 여러 방향에서 봅니다. 몸의 면이 향하는 쪽과 카메라가 옮겨 간 쪽을 구별해 보세요. 실제 화면에서는 재질과 조명까지 함께 영향을 줍니다. 다음 도식에서는 표면 방향 하나만 바꿔, 저장된 값과 그것을 읽는 비중을 분리해서 확인합니다.','A weight is a mixing proportion. Even with the same ingredients, changing their proportions changes the result. Directional lightmaps give more weight to components aligned with the surface.\n\nHere the robot is inspected from different viewpoints. Distinguish surface orientation from camera motion. Materials and lighting also affect the real image. Our diagram isolates surface direction so stored values and the weights used to read them can be considered separately.','가중치를혼합비율로 재정착','저장한 값은 그대로 / 읽는 비중 변경')
add('g38','책 표지를 펼치면 입체의 여러 면이 그림의 어느 위치를 쓸지 정할 수 있습니다. 이 주소가 유브이 좌표입니다. 기본색은 칠한 재료의 색, 거칠기는 반사의 퍼짐, 법선은 조명 계산에 쓸 방향입니다. 같은 표면도 이런 정보를 여러 장으로 나누어 다룹니다. 지금은 물체의 재질 자료를 보는 시연이며, 화면 픽셀의 지 버퍼 자체와는 구별합니다.','Unwrapping the book assigns image locations to its 3D faces: UV coordinates. Base color describes material color, roughness the spread of reflection, and normals the orientation used in lighting. One surface can have several property images. This is an object-material demonstration, distinct from a screen-space G-buffer.','UV/재질기본정보 정의','주소(UV) / 색 / 거칠기 / 방향')
add('g39','버퍼는 다음 계산에 쓸 값을 잠시 담아 두는 저장 공간입니다. 지 버퍼는 같은 화면 칸에 해당하는 표면의 여러 정보를 모읍니다. 지금 재질 화면의 색도 단순한 장식이 아니라 어떤 값을 표시하는지부터 봐야 합니다. 표면 정보를 읽고, 조명을 계산하고, 마지막 색을 만드는 순서로 연결해 보세요.','A buffer stores values for later processing. The G-buffer gathers properties of the visible surface at each image location. Colors in this material view represent specific data rather than decoration; their meaning must be identified. Connect surface information to lighting evaluation and then to the final color.','메모리/Gbuffer 초심자정의','표면 정보 → 조명 계산 → 최종 색')
add('g41','이 게임을 넣은 이유는 가느다란 윤곽이 많이 움직이는 브이알의 요구를 보기 위해서입니다. 손과 로봇, 파편의 가장자리를 따라가 보세요. 밝기를 계산하는 순서뿐 아니라, 한 픽셀을 물체가 얼마나 덮는지도 화면 품질에 영향을 줍니다. 이제 실제 확대 비교에서 그 가장자리를 보겠습니다.','This game illustrates VR’s moving thin edges. Follow the outlines of hands, robots and fragments. Image quality depends on pixel coverage as well as the order of lighting calculations. Next, inspect those edges in the magnified comparison.','불필요해보이는시연의역할선명화','빛 계산 순서 + 움직이는 가장자리 품질')
add('g42','안티앨리어싱은 계단처럼 거친 가장자리나 깜빡임을 줄이는 처리입니다. 멀티샘플은 픽셀 안의 여러 위치에서 물체가 덮는지 검사합니다. 네 위치 중 두 곳을 덮는다면 경계를 절반 정도 덮은 것으로 표현할 수 있죠. 이 예시는 덮임 설명이며 게임의 실제 샘플 수를 단정하는 숫자는 아닙니다.\n\n확대창에서 선이 어떻게 달라지는지 보세요. 선의 덮임을 여러 번 검사한다고 모든 재질과 조명을 그 횟수만큼 다시 계산하는 것은 아닙니다. 비용은 엔진 구현과 설정에 따라 달라집니다. 그래서 포워드와 디퍼드는 이름의 신구보다 필요한 화질, 기능, 메모리 비용을 함께 보고 선택합니다.','Anti-aliasing reduces jagged or unstable image edges. Multisampling tests coverage at several positions inside a pixel. If two of four positions are covered, the edge can contribute roughly half the coverage; this is an illustrative example, not a claim about the game’s sample setting.\n\nObserve the magnified line. Multiple coverage tests do not necessarily repeat every material and lighting computation that many times. Cost depends on implementation and settings. Forward versus Deferred is therefore a choice involving image quality, features and memory costs, not simply which name is newer.','AA/MSAA 정의와비용제한','픽셀 안 여러 덮임 검사 → 가장자리 표현')

base={l:rd(P/f'script/narration.{l}.json') for l in ['ko','en']}
guides={l:rd(P/f'script/native-guides-v2.{l}.json') for l in ['ko','en']}
timeline=rd(P/'production/local/threejs-revision-v1/pair-caption-decoder-v3/plan.json')
vo={x['key']:x for x in timeline['voice']}
for i,c in enumerate(changes):
 c['ttsSceneId']=f'b{i+1:03d}';c['baselineVoice']=vo[c['key']]
 c['baselineSpeechSeconds']=vo[c['key']]['samples']/24000
 if c['key'].startswith('g'):
  for l in ['ko','en']:
   s=next(s for s in guides[l]['scenes'] if s['id']==c['key']);c['old'+l.upper()]='\n\n'.join(s['lines']);s['lines']=c[l].split('\n\n')
 else:
  sid,pi=c['key'].split('-p')
  for l in ['ko','en']:
   s=next(s for s in base[l]['scenes'] if s['id']==sid);c['old'+l.upper()]=s['lines'][int(pi)-1];s['lines'][int(pi)-1]=c[l]
 c['characterRatio']=round(len(c['ko'])/len(c['oldKO']),3)
 c['ttsEstimatedSeconds']=round(c['baselineSpeechSeconds']*c['characterRatio'],2)
for l in ['ko','en']:
 wr(P/f'script/beginner-v1.{l}.json',base[l]);wr(P/f'script/beginner-guides-v1.{l}.json',guides[l])
 wr(P/f'script/beginner-changes-v1.{l}.json',dict(project='game-lighting-history-01',language=l,title='초심자 설명 보강 — 변경 발화만',scenes=[dict(id=c['ttsSceneId'],title=c['key']+' '+c['beginnerGoal'],lines=c[l].split('\n\n')) for c in changes]))
manifest=rd(P/'production/native-guides-v1.project.json')
manifest['paths']['script']='projects/game-lighting-history-01/script/beginner-changes-v1.ko.json';manifest['paths']['scriptEn']='projects/game-lighting-history-01/script/beginner-changes-v1.en.json'
manifest['tts'].update(outputDir='shared/output/narration/game-lighting-history-01/beginner-revision-v1',filenameStem='game-lighting-history-01-beginner-revision-v1',renderMode='scene',sceneGapSeconds=.72)
wr(D/'tts.project.json',manifest)
wr(D/'changes.json',dict(schemaVersion=1,createdAt=now,baselineVideoId='uT5FTLJx5_c',baselinePlan='production/local/threejs-revision-v1/pair-caption-decoder-v3/plan.json',rows=changes,completeKoEnDirectReview=False,measuredTimingApproved=False,policy='Keep useful claims, chronological order and actual3D depth; explain prerequisites adjacent to their first use. Change only listed speech. No shortening or audio speedup to fit slots.',hashes={l:sha(P/f'script/beginner-changes-v1.{l}.json') for l in ['ko','en']}))
print(json.dumps(dict(changed=len(changes),main=sum(not c['key'].startswith('g') for c in changes),guides=sum(c['key'].startswith('g') for c in changes),speechBaseline=sum(c['baselineSpeechSeconds'] for c in changes),speechEstimated=sum(c['ttsEstimatedSeconds'] for c in changes),longer=[(c['key'],c['baselineSpeechSeconds'],c['ttsEstimatedSeconds']) for c in changes if c['characterRatio']>1.12]),ensure_ascii=False))
